	//
	// B is laid out with j as the fastest dimension:
	//   B_struct = scalar ^ j_vec ^ i_vec
	// so that, for fixed row i, B[i][j] is contiguous in j. The optimized
	// kernel uses j as the innermost loop to exploit this.
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
