	using namespace noarr;

	// Column tiling for B along j; chosen conservatively, can be tuned.
	constexpr std::size_t tile_j = 64;

	// Build a traverser over (B, A) that:
	//   - splits 'j' into tiles of size tile_j: major dim 'J', minor dim 'j'
	//   - hoists 'J' so that column tiles are processed together
	// The states we see in lambdas still use only the original indices
	// ('i', 'j', 'k'); 'J' and the guard dimension are internal to traverser.
	auto trav = traverser(B, A).order(
		noarr::into_blocks_dynamic<'j', 'J', 'j', 't'>(tile_j) ^ // 't' guards partial tiles
		noarr::hoist<'J'>()
	);

	#pragma scop
	trav.template for_dims<'i'>([=](auto trav_i) {
		// 'i' is the row of B being updated; for each fixed column j,
		// B[i, j] depends on B[k, j] for k > i, so i must be processed
		// in increasing order for correctness.
		auto state_i = trav_i.state();
		auto i = get_index<'i'>(state_i);

		// --- Triangular update phase ---
		// B[i, j] += sum_{k=i+1}^{M-1} A[k, i] * B[k, j]
		trav_i.template for_dims<'k'>([=](auto trav_k) {
			auto state_k = trav_k.state();
			auto k = get_index<'k'>(state_k);

			// Enforce the triangular condition k > i
			if (k <= i)
				return;

			// A[k][i] access:
			//   layout chosen so that, for fixed i, increasing k walks
			//   unit-stride through memory.
			auto a_state = noarr::idx<'i', 'k'>(k, i);
			num_t a_ki = A[a_state];

			// For this (i, k) pair, update the entire row i across all columns j.
			// Thanks to the tiling in 'j', traverser walks B[i, *] and B[k, *]
			// in cache-friendly column blocks while exposing contiguous j
			// accesses to the innermost loop.
			trav_k.template for_each<'j'>([=](auto state_ijk) {
				auto [ii, j] = get_indices<'i', 'j'>(state_ijk);
				(void)ii; // always equal to 'i'

				// B[k][j] -> B at (i = k, j = j)
				auto bkj_state = noarr::idx<'i', 'j'>(k, j);

				// In-place accumulation into B[i, j]; B[k, j] on the RHS is
				// still the original value because row k has not been updated
				// yet (we process rows in increasing i).
				B[state_ijk] += a_ki * B[bkj_state];
			});
		});

