	//        splits dimension 'j' into tiles 'J' (outer) and 'j' (inner).
	//  - hoist<'J'>():
	//        makes the column-tile index 'J' the outer-most traversed dim.
	//  - into_blocks_dynamic<'k','K','k','u'>(tile_k):
	//        similarly tiles the reduction dimension 'k' into 'K' and 'k'.
	//  - hoist<'K'>():
	//        makes the k-tile index 'K' outer with respect to the inner 'k'.
	//
