		noarr::into_blocks_dynamic<'j', 'J', 'j', 't'>(tile_j) ^ noarr::hoist<'J'>()
		^ noarr::into_blocks_dynamic<'k', 'K', 'k', 'u'>(tile_k) ^ noarr::hoist<'K'>();

