	// Phase 1: triangular update
	// ---------------------------
	//
	// B[i,j] += sum_{k>i} A[k,i] * B[k,j]
	//
	// Nest structure (ignoring tiles):
	//   for i (sequential):
	//     for k in (i+1 .. M-1):
	//       a_ki = A[k,i];
	//       for j:
	//         B[i,j] += a_ki * B[k,j];
