	//   - 'i'  – rows, kept sequential to respect dependencies,
	//   - 'K','k' – k-tiles and local k (reduction),
	//   - inner j over the current tile.
	noarr::traverser(A, B)
		.order(blocked_order)
		.template for_dims<'J'>([=](auto trav_J) {
