				auto state_i = trav_JI.state();
				std::size_t i = noarr::get_index<'i'>(state_i);

				// k-tiles
				trav_JI.template for_dims<'K'>([=](auto trav_JIK) {
					// trav_JIK: fixed J, i, K, still has dims 'k', 'j'

					// Local k inside the current tile
					trav_JIK.template for_dims<'k'>([=](auto trav_JIKk) {
						// trav_JIKk: fixed J, i, K, k, still has dim 'j'

						auto state_ik = trav_JIKk.state();
						std::size_t k = noarr::get_index<'k'>(state_ik);

						// Enforce the triangular condition: only k > i contribute.
						if (k <= i)
							return;

						// Load A[k][i] once for this (i,k) and reuse across all j
						// in the current column tile.
						//
						// A[k][i] in the original C code corresponds to
						//   A at (i = k, k = i) in our (i,k) indexing.
						num_t a_ki = A[noarr::idx<'i', 'k'>(k, i)];

