						// Thanks to the original B layout (i x j, row-major),
						// B[i,j] and B[k,j] for consecutive j are contiguous
						// in memory, so this loop is vectorization-friendly.
						trav_JIKk.for_each([&](auto state) {
							std::size_t j = noarr::get_index<'j'>(state);

							auto bij_state = noarr::idx<'i', 'j'>(i, j);
							auto bkj_state = noarr::idx<'i', 'j'>(k, j);

