		// --- Triangular update: B[i, j] += sum_{k=i+1}^{M-1} A[k, i] * B[k, j] ---

		// Iterate k as a traverser dimension.
		// B does not have 'k', but it is present in A; traverser will provide
		// a joint state with 'i' and 'k' (and later 'j') and B will just
		// ignore 'k'.
		trav_i.template for_dims<'k'>([=](auto trav_ik) {
			auto state_ik = trav_ik.state();
			std::size_t k = get_index<'k'>(state_ik);

			// Respect the triangular condition k > i.
			if (k <= i)
				return;

			// A is stored as A[i, k] (row-major in (i,k)), but the algorithm
			// needs A[k, i]. We construct the appropriate state explicitly.
			num_t a_ki = A[noarr::idx<'i', 'k'>(k, i)];

			// For this fixed pair (i, k), sweep all columns j. Because B is
			// laid out with 'j' as the inner dimension, this is a SAXPY-like
			// update with unit-stride accesses in j for both B[i, *] and
			// B[k, *].
			trav_ik.template for_each<'j'>([&](auto state_ikj) {
				std::size_t j = get_index<'j'>(state_ikj);

				// Build states for B[i, j] (row being updated) and B[k, j]
				// (source row). We keep a_ki in a register and reuse it
				// across the whole row.
				auto state_i_j = noarr::idx<'i', 'j'>(i, j);
				auto state_k_j = noarr::idx<'i', 'j'>(k, j);

				B[state_i_j] += a_ki * B[state_k_j];
			});
		});

		// --- Final scaling: B[i, j] *= alpha for all columns j ---

		// This second phase is separate to mirror the original kernel's
		// "B[i][j] = alpha * B[i][j]" and keeps that multiply outside the
		// k-reduction, helping the compiler to keep the inner loop tight.
		trav_i.template for_each<'j'>([&](auto state_ij) {
			B[state_ij] *= alpha;
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;

	// set lengths for all dimensions used
	auto set_lengths = noarr::set_length<'i'>(m)
	                 ^ noarr::set_length<'j'>(n)
	                 ^ noarr::set_length<'k'>(m);

	// allocate bags
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths); // M x M
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths); // M x N

	// initialize data
	init_array(alpha, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_trmm(alpha, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (for DCE prevention / correctness check)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
